const config = $('Master Configuration Form').item.json;
const useCase = config.useCase;
const personality = config.voicePersonality;
const industry = config.industry;
const orgName = config.organizationName;
const location = config.targetLocationRegion || 'Global';
const integrations = config.activeIntegrations || [];

// Define personality templates
const personalityTraits = {
  professional: "professional, courteous, and business-focused",
  friendly: "warm, approachable, and conversational", 
  empathetic: "understanding, patient, and compassionate",
  authoritative: "confident, knowledgeable, and decisive",
  casual: "relaxed, informal, and easy-going",
  technical: "precise, analytical, and detail-oriented"
};

// Define use case templates
const useCasePrompts = {
  sales: {
    role: "sales representative",
    objectives: [
      "Qualify leads and gather contact information",
      "Schedule sales meetings and demos", 
      "Capture prospect needs and pain points",
      "Route qualified leads to appropriate sales team",
      "Follow up on proposals and quotes"
    ],
    capabilities: [
      "Lead qualification and scoring",
      "Product information and pricing",
      "Demo scheduling and calendar management",
      "Competitor analysis and positioning",
      "CRM integration and data capture"
    ]
  },
  helpdesk: {
    role: "customer support specialist",
    objectives: [
      "Resolve customer issues efficiently",
      "Create and manage support tickets",
      "Escalate complex problems to human agents",
      "Provide troubleshooting guidance",
      "Track issue resolution and customer satisfaction"
    ],
    capabilities: [
      "Issue diagnosis and troubleshooting",
      "Knowledge base search and recommendations",
      "Ticket creation and status tracking",
      "Escalation procedures and routing",
      "Customer satisfaction surveys"
    ]
  },
  healthcare: {
    role: "healthcare assistant",
    objectives: [
      "Help patients find healthcare providers",
      "Schedule medical appointments",
      "Provide health information and resources",
      "Assist with insurance and billing inquiries",
      "Ensure HIPAA compliance in all interactions"
    ],
    capabilities: [
      "Provider search by specialty and location",
      "Appointment scheduling and reminders",
      "Health information lookup",
      "Insurance verification assistance",
      "Emergency services information"
    ]
  },
  general_business: {
    role: "business assistant", 
    objectives: [
      "Answer general business inquiries",
      "Capture visitor information",
      "Route calls to appropriate departments",
      "Provide company information",
      "Schedule appointments and meetings"
    ],
    capabilities: [
      "Company information and services",
      "Contact routing and directory assistance",
      "Basic appointment scheduling",
      "Information capture and CRM updates",
      "Follow-up coordination"
    ]
  },
  lead_generation: {
    role: "lead generation specialist",
    objectives: [
      "Identify and qualify potential customers",
      "Capture detailed lead information",
      "Assess buying intent and timeline",
      "Score leads for prioritization",
      "Schedule follow-up activities"
    ],
    capabilities: [
      "Lead qualification frameworks (BANT, MEDDIC)",
      "Competitive landscape assessment",
      "Budget and timeline identification",
      "Decision maker mapping",
      "Lead scoring and prioritization"
    ]
  },
  customer_support: {
    role: "customer success manager",
    objectives: [
      "Ensure customer satisfaction and retention",
      "Resolve account issues and concerns",
      "Identify upselling opportunities",
      "Gather customer feedback",
      "Coordinate with internal teams"
    ],
    capabilities: [
      "Account status and history review",
      "Issue resolution and escalation",
      "Feature requests and feedback collection",
      "Renewal and expansion discussions",
      "Customer health monitoring"
    ]
  },
  appointment_booking: {
    role: "scheduling coordinator",
    objectives: [
      "Efficiently schedule appointments",
      "Manage calendar availability",
      "Send confirmations and reminders",
      "Handle cancellations and rescheduling",
      "Optimize scheduling efficiency"
    ],
    capabilities: [
      "Real-time calendar management",
      "Automated confirmation and reminders",
      "Conflict resolution and rescheduling",
      "Resource and room booking",
      "Waitlist management"
    ]
  },
  custom: {
    role: "intelligent assistant",
    objectives: [
      "Adapt to specific business requirements",
      "Provide flexible interaction capabilities",
      "Integrate with existing workflows",
      "Support custom business processes",
      "Scale with changing needs"
    ],
    capabilities: [
      "Configurable conversation flows",
      "Custom integration endpoints",
      "Flexible data capture",
      "Adaptive response generation",
      "Workflow automation"
    ]
  }
};

// Get use case configuration
const useCaseConfig = useCasePrompts[useCase] || useCasePrompts.custom;

// Generate system prompt
const systemPrompt = `You are an intelligent ${useCaseConfig.role} for ${orgName}, a ${industry} company serving ${location}.

Personality: You are ${personalityTraits[personality]} in all interactions.

Your primary objectives:
${useCaseConfig.objectives.map(obj => `- ${obj}`).join('\n')}

Your capabilities include:
${useCaseConfig.capabilities.map(cap => `- ${cap}`).join('\n')}

Available integrations and tools:
${integrations.includes('hubspot_crm') ? '- CRM management via save_contact_to_crm for customer data' : ''}
${integrations.includes('resend_email') ? '- Email notifications via send_email_notification for follow-ups' : ''}
${integrations.includes('tavily_search') ? '- Web research via search_web_information for current information' : ''}
${integrations.includes('calendly_scheduling') ? '- Appointment scheduling via schedule_appointment for meetings' : ''}
${integrations.includes('freshdesk_support') ? '- Support ticket creation via create_support_ticket for issues' : ''}
${integrations.includes('vonage_sms') ? '- SMS notifications via send_sms_notification for urgent updates' : ''}
${integrations.includes('firecrawl_scraping') ? '- Website analysis via analyze_website for research' : ''}
${integrations.includes('brave_search') ? '- Enhanced search via enhanced_web_search for detailed research' : ''}
${integrations.includes('supabase_database') ? '- Data storage via save_interaction_data for record keeping' : ''}

Conversation guidelines:
1. Always be ${personalityTraits[personality]}
2. Ask clarifying questions to understand needs fully
3. Use appropriate tools to gather or provide information
4. Confirm actions before executing them
5. Provide clear next steps and follow-up information
6. Respect customer privacy and data protection
${ config.hipaaComplianceRequired === 'Yes' ? '7. Maintain HIPAA compliance - never discuss specific medical details\n8. Use secure data handling for all health-related information' : ''}

When greeting customers, introduce yourself and your capabilities relevant to their likely needs.`;

// Generate voice configuration
const voiceConfig = {
  provider: "11labs",
  voiceId: personality === 'empathetic' ? "21m00Tcm4TlvDq8ikWAM" : // Rachel - warm
           personality === 'authoritative' ? "2EiwWnXFnvU5JabPnv8n" : // Clyde - confident
           personality === 'friendly' ? "AZnzlk1XvdvUeBnXmlld" : // Domi - friendly
           personality === 'professional' ? "EXAVITQu4vr4xnSDxMaL" : // Bella - professional
           personality === 'casual' ? "ErXwobaYiN019PkySvjV" : // Antoni - casual
           "pNInz6obpgDQGcFmaJgB" // Adam - technical/default
};

// Generate first message
const firstMessage = useCase === 'sales' ? 
  `Hello! I'm ${orgName}'s AI sales assistant. I'm here to help you learn about our solutions and see if we're a good fit for your needs. How can I assist you today?` :
useCase === 'helpdesk' ?
  `Hi! I'm ${orgName}'s AI support assistant. I'm here to help resolve any issues or questions you have. What can I help you with today?` :
useCase === 'healthcare' ?
  `Hello! I'm ${orgName}'s healthcare assistant. I can help you find providers, schedule appointments, and answer health-related questions. How may I assist you today?` :
`Hello! I'm ${orgName}'s AI assistant. I'm here to help with your inquiries and connect you with the right information or people. What can I help you with today?`;

return {
  systemPrompt,
  voiceConfig,
  firstMessage,
  useCaseConfig,
  personalityType: personality,
  integrationCount: integrations.length
};

const config = $('Master Configuration Form').item.json;
const serverUrl = config.backendServerUrl;
const useCase = config.useCase;
const integrations = config.activeIntegrations || [];
const orgName = config.organizationName;

// Base tool configurations for each integration
const toolTemplates = {
  hubspot_crm: {
    "async": true,
    "messages": [
      {
        "type": "request-start",
        "content": "Saving contact information to CRM..."
      },
      {
        "type": "request-complete",
        "content": "Contact saved successfully to CRM."
      }
    ],
    "type": "function",
    "function": {
      "name": "save_contact_to_crm",
      "description": "Save customer contact information to HubSpot CRM system for follow-up and relationship management.",
      "parameters": {
        "type": "object",
        "properties": {
          "integration_name": {
            "type": "string",
            "default": "hubspot_consolidated",
            "description": "Integration service name"
          },
          "action": {
            "type": "string",
            "default": "create_contact",
            "description": "CRM action to execute"
          },
          "firstName": {
            "type": "string",
            "description": "Contact's first name"
          },
          "lastName": {
            "type": "string",
            "description": "Contact's last name"
          },
          "email": {
            "type": "string",
            "description": "Contact's email address"
          },
          "phone": {
            "type": "string",
            "description": "Contact's phone number"
          },
          "company": {
            "type": "string",
            "description": "Company name"
          },
          "jobTitle": {
            "type": "string",
            "description": "Job title or position"
          },
          "leadSource": {
            "type": "string",
            "default": "voice_assistant",
            "description": "Source of the lead"
          },
          "notes": {
            "type": "string",
            "description": "Additional notes from conversation"
          },
          "useCase": {
            "type": "string", 
            "default": useCase,
            "description": "Use case context"
          }
        },
        "required": ["firstName", "email"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/integration-webhooks/execute`,
      "method": "POST"
    }
  },

  resend_email: {
    "async": true,
    "messages": [
      {
        "type": "request-start",
        "content": "Sending email notification..."
      },
      {
        "type": "request-complete",
        "content": "Email sent successfully."
      }
    ],
    "type": "function",
    "function": {
      "name": "send_email_notification",
      "description": "Send email notifications for follow-ups, confirmations, or information sharing.",
      "parameters": {
        "type": "object",
        "properties": {
          "integration_name": {
            "type": "string",
            "default": "resend_consolidated",
            "description": "Integration service name"
          },
          "action": {
            "type": "string",
            "default": "send_email",
            "description": "Email action to execute"
          },
          "to_email": {
            "type": "string",
            "description": "Recipient email address"
          },
          "subject": {
            "type": "string",
            "description": "Email subject line"
          },
          "message": {
            "type": "string",
            "description": "Email message content"
          },
          "customer_name": {
            "type": "string",
            "description": "Customer's name for personalization"
          },
          "call_summary": {
            "type": "string",
            "description": "Summary of the conversation"
          },
          "sender_name": {
            "type": "string",
            "default": orgName,
            "description": "Sender organization name"
          }
        },
        "required": ["to_email", "subject", "message"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/integration-webhooks/execute`,
      "method": "POST"
    }
  },

  tavily_search: {
    "async": true,
    "messages": [
      {
        "type": "request-start",
        "content": "Searching for current information..."
      },
      {
        "type": "request-complete",
        "content": "Search completed."
      }
    ],
    "type": "function",
    "function": {
      "name": "search_web_information",
      "description": "Search the web for current information, research, or answers to customer questions.",
      "parameters": {
        "type": "object",
        "properties": {
          "integration_name": {
            "type": "string",
            "default": "tavily_consolidated",
            "description": "Integration service name"
          },
          "action": {
            "type": "string",
            "default": "search",
            "description": "Search action to execute"
          },
          "query": {
            "type": "string",
            "description": "Search query for information lookup"
          },
          "max_results": {
            "type": "integer",
            "default": 5,
            "description": "Maximum number of search results"
          },
          "include_domains": {
            "type": "string",
            "description": "Specific domains to include in search"
          }
        },
        "required": ["query"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/integration-webhooks/execute`,
      "method": "POST"
    }
  },

  calendly_scheduling: {
    "async": true,
    "messages": [
      {
        "type": "request-start",
        "content": "Scheduling appointment..."
      },
      {
        "type": "request-complete",
        "content": "Appointment scheduled successfully."
      }
    ],
    "type": "function",
    "function": {
      "name": "schedule_appointment",
      "description": "Schedule appointments, meetings, or calls using calendar integration.",
      "parameters": {
        "type": "object",
        "properties": {
          "integration_name": {
            "type": "string",
            "default": "calendly_consolidated",
            "description": "Integration service name"
          },
          "action": {
            "type": "string",
            "default": "create_event",
            "description": "Calendar action to execute"
          },
          "customer_name": {
            "type": "string",
            "description": "Customer's full name"
          },
          "customer_email": {
            "type": "string",
            "description": "Customer's email address"
          },
          "appointment_date": {
            "type": "string",
            "description": "Preferred appointment date (YYYY-MM-DD)"
          },
          "appointment_time": {
            "type": "string",
            "description": "Preferred appointment time (HH:MM)"
          },
          "duration_minutes": {
            "type": "integer",
            "default": 30,
            "description": "Duration in minutes"
          },
          "meeting_type": {
            "type": "string",
            "description": "Type of meeting or appointment"
          },
          "notes": {
            "type": "string",
            "description": "Additional notes or requirements"
          }
        },
        "required": ["customer_name", "customer_email", "appointment_date", "appointment_time"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/integration-webhooks/execute`,
      "method": "POST"
    }
  },

  freshdesk_support: {
    "async": true,
    "messages": [
      {
        "type": "request-start",
        "content": "Creating support ticket..."
      },
      {
        "type": "request-complete",
        "content": "Support ticket created successfully."
      }
    ],
    "type": "function",
    "function": {
      "name": "create_support_ticket",
      "description": "Create support tickets for issues that require human assistance.",
      "parameters": {
        "type": "object",
        "properties": {
          "integration_name": {
            "type": "string",
            "default": "freshdesk_consolidated",
            "description": "Integration service name"
          },
          "action": {
            "type": "string",
            "default": "create_ticket",
            "description": "Support action to execute"
          },
          "customer_name": {
            "type": "string",
            "description": "Customer's name"
          },
          "customer_email": {
            "type": "string",
            "description": "Customer's email address"
          },
          "subject": {
            "type": "string",
            "description": "Ticket subject/title"
          },
          "description": {
            "type": "string",
            "description": "Detailed description of the issue"
          },
          "priority": {
            "type": "string",
            "enum": ["low", "medium", "high", "urgent"],
            "default": "medium",
            "description": "Ticket priority level"
          },
          "category": {
            "type": "string",
            "description": "Issue category or type"
          }
        },
        "required": ["customer_name", "customer_email", "subject", "description"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/integration-webhooks/execute`,
      "method": "POST"
    }
  },

  vonage_sms: {
    "async": true,
    "messages": [
      {
        "type": "request-start",
        "content": "Sending SMS notification..."
      },
      {
        "type": "request-complete",
        "content": "SMS sent successfully."
      }
    ],
    "type": "function",
    "function": {
      "name": "send_sms_notification",
      "description": "Send SMS notifications for urgent updates or confirmations.",
      "parameters": {
        "type": "object",
        "properties": {
          "integration_name": {
            "type": "string",
            "default": "vonage_consolidated",
            "description": "Integration service name"
          },
          "action": {
            "type": "string",
            "default": "send_sms",
            "description": "SMS action to execute"
          },
          "phone_number": {
            "type": "string",
            "description": "Recipient phone number (international format)"
          },
          "message": {
            "type": "string",
            "description": "SMS message content (max 160 characters)"
          },
          "sender_name": {
            "type": "string",
            "default": orgName,
            "description": "Sender name or ID"
          }
        },
        "required": ["phone_number", "message"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/integration-webhooks/execute`,
      "method": "POST"
    }
  },

  supabase_database: {
    "async": true,
    "messages": [
      {
        "type": "request-start",
        "content": "Saving interaction data..."
      },
      {
        "type": "request-complete",
        "content": "Data saved successfully."
      }
    ],
    "type": "function",
    "function": {
      "name": "save_interaction_data",
      "description": "Save conversation data and customer interactions to database for analytics.",
      "parameters": {
        "type": "object",
        "properties": {
          "customer_name": {
            "type": "string",
            "description": "Customer's name"
          },
          "customer_email": {
            "type": "string",
            "description": "Customer's email"
          },
          "customer_phone": {
            "type": "string",
            "description": "Customer's phone number"
          },
          "call_purpose": {
            "type": "string",
            "description": "Purpose or intent of the call"
          },
          "call_outcome": {
            "type": "string",
            "description": "Result or outcome of the call"
          },
          "next_action": {
            "type": "string",
            "description": "Planned follow-up action"
          },
          "use_case": {
            "type": "string",
            "default": useCase,
            "description": "Use case context"
          }
        },
        "required": ["customer_name", "call_purpose"]
      }
    },
    "server": {
      "timeout": 15,
      "url": `${serverUrl}/integrations/supabase/webhook`,
      "method": "POST"
    }
  }
};

// Generate tools based on selected integrations
const tools = [];
integrations.forEach(integration => {
  if (toolTemplates[integration]) {
    tools.push(toolTemplates[integration]);
  }
});

// Add use case specific enhancements
if (useCase === 'sales') {
  // Enhance CRM tool for sales context
  const crmTool = tools.find(t => t.function.name === 'save_contact_to_crm');
  if (crmTool) {
    crmTool.function.parameters.properties.leadScore = {
      "type": "integer",
      "description": "Lead score (1-10) based on qualification"
    };
    crmTool.function.parameters.properties.budget = {
      "type": "string",
      "description": "Estimated budget range"
    };
    crmTool.function.parameters.properties.timeline = {
      "type": "string",
      "description": "Purchase timeline"
    };
  }
} else if (useCase === 'helpdesk') {
  // Enhance support tools for helpdesk context
  const supportTool = tools.find(t => t.function.name === 'create_support_ticket');
  if (supportTool) {
    supportTool.function.parameters.properties.urgency = {
      "type": "string",
      "enum": ["low", "normal", "high", "critical"],
      "default": "normal",
      "description": "Issue urgency level"
    };
    supportTool.function.parameters.properties.affectedUsers = {
      "type": "integer",
      "description": "Number of affected users"
    };
  }
} else if (useCase === 'healthcare') {
  // Add HIPAA compliance notes
  tools.forEach(tool => {
    if (tool.function.parameters.properties.notes) {
      tool.function.parameters.properties.notes.description += " (HIPAA compliant - no PHI)";
    }
  });
}

return {
  tools,
  toolCount: tools.length,
  integrationTypes: integrations,
  useCaseOptimizations: useCase
};

